 evidence={'build':'1003n1','cross_study_diagnostic':read(ROOT/'runs/btc-network-report-20261003/cross-study-identity.json'),'account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'uncertainty':unc,'diagnostics':diag,'activity':activity,'control_identity':identity,'forecast_summary':fc,'scope':'BTC-only development; public aggregate address and transaction counts, not persons or wallets; assumed D+2 availability, not first vintages; no accepted strategy'}
